function isValid(s: string): boolean {
  // Нечётная длина — какая-то скобка точно останется без пары
  if (s.length % 2 === 1) return false;

  // Закрывающая скобка -> парная открывающая
  const pairs: Record<string, string> = { ')': '(', ']': '[', '}': '{' };
  const stack: string[] = [];

  for (const c of s) {
    const open = pairs[c];
    if (open === undefined) {
      // Открывающая скобка — откладываем до её закрытия
      stack.push(c);
    } else if (stack.pop() !== open) {
      // Закрывающая должна закрыть ПОСЛЕДНЮЮ открытую скобку того же типа.
      // Пустой стек (pop вернёт undefined) — тоже ошибка
      return false;
    }
  }

  // Все открытые скобки должны быть закрыты
  return stack.length === 0;
}

// Время: O(n)
// Память: O(n) — в худшем случае все скобки открывающие
